package co.edu.greenroute.analitica;

import co.edu.greenroute.excepciones.DatosInvalidosException;
import co.edu.greenroute.util.LectorCSV;

import java.nio.file.Path;

/** Factor de velocidad por hora del día, aprendido en Python (perfil_horario.csv): simula el tráfico. */
public class PerfilHorario {
    private final double[] indiceActividad = new double[24];
    private final double[] factorVelocidad = new double[24];
    private final String fuente;

    private PerfilHorario(String fuente) {
        this.fuente = fuente;
    }

    public static PerfilHorario cargar(Path archivo) {
        PerfilHorario p = new PerfilHorario("Modelo ML (perfil_horario.csv)");
        try {
            LectorCSV.leer(archivo, fila -> {
                int h = Integer.parseInt(fila.get("hora"));
                p.indiceActividad[h] = Double.parseDouble(fila.get("indice_actividad"));
                p.factorVelocidad[h] = Double.parseDouble(fila.get("factor_velocidad"));
            });
            return p;
        } catch (DatosInvalidosException | RuntimeException e) {
            System.err.println("[PerfilHorario] " + e.getMessage() + " — se usa un perfil por defecto");
            return porDefecto();
        }
    }

    public static PerfilHorario porDefecto() {
        PerfilHorario p = new PerfilHorario("Perfil por defecto");
        for (int h = 0; h < 24; h++) {
            double pico = Math.exp(-Math.pow(h - 7, 2) / 4.0) + Math.exp(-Math.pow(h - 18, 2) / 5.0);
            p.indiceActividad[h] = Math.min(1, 0.15 + pico);
            p.factorVelocidad[h] = 1 - 0.45 * p.indiceActividad[h];
        }
        return p;
    }

    public double factorVelocidad(int hora) {
        return factorVelocidad[Math.floorMod(hora, 24)];
    }

    public double indiceActividad(int hora) {
        return indiceActividad[Math.floorMod(hora, 24)];
    }

    public double[] getFactores() {
        return factorVelocidad.clone();
    }

    public double[] getIndices() {
        return indiceActividad.clone();
    }

    public String getFuente() {
        return fuente;
    }
}

package co.edu.greenroute.api;

import co.edu.greenroute.excepciones.DatosInvalidosException;
import co.edu.greenroute.excepciones.GreenRouteException;
import co.edu.greenroute.modelo.Coordenada;
import co.edu.greenroute.ruteo.AEstrella;
import co.edu.greenroute.ruteo.AlgoritmoRuta;
import co.edu.greenroute.ruteo.Criterio;
import co.edu.greenroute.ruteo.Dijkstra;
import co.edu.greenroute.ruteo.Ruta;
import co.edu.greenroute.servicio.OpcionTransporte;
import co.edu.greenroute.servicio.PlanificadorRutas;
import co.edu.greenroute.util.Json;
import co.edu.greenroute.util.LectorCSV;
import co.edu.greenroute.vehiculos.Recargable;
import co.edu.greenroute.vehiculos.Vehiculo;
import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpHandler;
import com.sun.net.httpserver.HttpServer;

import java.io.IOException;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.Executors;

/** Servidor HTTP: sirve la carpeta web y expone el API REST (/api/ruta, /api/comparar, ...) en JSON. */
public class ServidorWeb {
    private static final Map<String, String> TIPOS_MIME = new HashMap<>();

    static {
        TIPOS_MIME.put("html", "text/html; charset=utf-8");
        TIPOS_MIME.put("css", "text/css; charset=utf-8");
        TIPOS_MIME.put("js", "application/javascript; charset=utf-8");
        TIPOS_MIME.put("json", "application/json; charset=utf-8");
        TIPOS_MIME.put("geojson", "application/json; charset=utf-8");
        TIPOS_MIME.put("png", "image/png");
        TIPOS_MIME.put("jpg", "image/jpeg");
        TIPOS_MIME.put("svg", "image/svg+xml");
        TIPOS_MIME.put("ico", "image/x-icon");
        TIPOS_MIME.put("csv", "text/csv; charset=utf-8");
        TIPOS_MIME.put("mp4", "video/mp4");
    }

    private final PlanificadorRutas planificador;
    private final Path carpetaWeb;
    private final Path carpetaDatos;
    private HttpServer servidor;

    public ServidorWeb(PlanificadorRutas planificador, Path carpetaWeb, Path carpetaDatos) {
        this.planificador = planificador;
        this.carpetaWeb = carpetaWeb.toAbsolutePath().normalize();
        this.carpetaDatos = carpetaDatos;
    }

    public void iniciar(int puerto) throws IOException {
        servidor = HttpServer.create(new InetSocketAddress(puerto), 0);
        servidor.createContext("/api/estado", api(this::estado));
        servidor.createContext("/api/vehiculos", api(q -> vehiculos()));
        servidor.createContext("/api/puntos", api(q -> puntos()));
        servidor.createContext("/api/ruta", api(this::ruta));
        servidor.createContext("/api/alternativas", api(this::alternativas));
        servidor.createContext("/api/comparar", api(this::comparar));
        servidor.createContext("/api/algoritmos", api(this::algoritmos));
        servidor.createContext("/", this::archivoEstatico);
        servidor.setExecutor(Executors.newFixedThreadPool(8));
        servidor.start();
    }

    private Object estado(Map<String, String> q) {
        return Json.obj(
                "nodos", planificador.getRed().totalNodos(),
                "tramos", planificador.getRed().totalTramos(),
                "kmViales", planificador.getRed().getKmViales(),
                "kmFluviales", planificador.getRed().getKmFluviales(),
                "vehiculos", planificador.getFlota().tamano(),
                "algoritmo", planificador.getAlgoritmo().getNombre(),
                "perfilFuente", planificador.getPerfil().getFuente(),
                "factorVelocidadHora", planificador.getPerfil().getFactores(),
                "indiceActividadHora", planificador.getPerfil().getIndices());
    }

    private Object vehiculos() {
        List<Object> lista = new ArrayList<>();
        for (Vehiculo v : planificador.getFlota().getVehiculos()) {
            Map<String, Object> m = Json.obj(
                    "id", v.getId(),
                    "nombre", v.getNombre(),
                    "clase", v.getClass().getSimpleName(),
                    "superclase", v.getClass().getSuperclass().getSimpleName(),
                    "medio", v.getMedio().name(),
                    "energia", v.getTipoEnergia().getDescripcion(),
                    "unidad", v.getTipoEnergia().getUnidad(),
                    "factorEmision", v.getTipoEnergia().getFactorEmision(),
                    "tecnologia", v.getTecnologia(),
                    "capacidadKg", v.getCapacidadKg(),
                    "pesoVacioKg", v.getPesoVacioKg(),
                    "velocidadMaxKmh", v.getVelocidadMaxKmh(),
                    "recargable", v instanceof Recargable);
            if (v instanceof Recargable) {
                m.put("bateriaKWh", ((Recargable) v).getCapacidadBateriaKWh());
            }
            lista.add(m);
        }
        return lista;
    }

    private Object puntos() throws DatosInvalidosException {
        List<Object> lista = new ArrayList<>();
        LectorCSV.leer(carpetaDatos.resolve("puntos.csv"), f -> lista.add(Json.obj(
                "nombre", f.get("nombre"), "categoria", f.get("categoria"),
                "lat", Double.parseDouble(f.get("lat")), "lon", Double.parseDouble(f.get("lon")))));
        return lista;
    }

    private Object ruta(Map<String, String> q) throws GreenRouteException {
        Vehiculo v = vehiculo(q);
        Ruta r = planificador.planificar(coord(q, "o"), coord(q, "d"), v,
                Criterio.desdeTexto(q.get("criterio")), hora(q), carga(q));
        return r.aMapa(true);
    }

    private Object alternativas(Map<String, String> q) throws GreenRouteException {
        Map<Criterio, Ruta> alt = planificador.alternativas(coord(q, "o"), coord(q, "d"), vehiculo(q),
                hora(q), carga(q));
        List<Object> lista = new ArrayList<>();
        for (Ruta r : alt.values()) {
            lista.add(r.aMapa(true));
        }
        return lista;
    }

    private Object comparar(Map<String, String> q) throws GreenRouteException {
        List<OpcionTransporte> opciones = planificador.compararFlota(coord(q, "o"), coord(q, "d"),
                hora(q), carga(q), Criterio.desdeTexto(q.get("criterio")));
        List<Object> lista = new ArrayList<>();
        for (OpcionTransporte op : opciones) {
            lista.add(op.aMapa());
        }
        Optional<OpcionTransporte> mejor = planificador.recomendar(opciones);
        return Json.obj("opciones", lista,
                "recomendado", mejor.map(op -> op.getVehiculo().getId()).orElse(null));
    }

    private Object algoritmos(Map<String, String> q) throws GreenRouteException {
        Vehiculo v = vehiculo(q);
        List<Object> lista = new ArrayList<>();
        for (AlgoritmoRuta alg : new AlgoritmoRuta[]{new Dijkstra(), new AEstrella()}) {
            PlanificadorRutas p = new PlanificadorRutas(planificador.getRed(), planificador.getFlota(),
                    planificador.getPerfil(), alg);
            Ruta r = p.planificar(coord(q, "o"), coord(q, "d"), v, Criterio.desdeTexto(q.get("criterio")),
                    hora(q), carga(q));
            lista.add(Json.obj("algoritmo", alg.getNombre(), "nodosExplorados", r.getNodosExplorados(),
                    "calculoMs", r.getTiempoCalculoMs(), "distanciaKm", r.getDistanciaKm(),
                    "emisionKgCO2", r.getEmisionKgCO2()));
        }
        return lista;
    }

    private Vehiculo vehiculo(Map<String, String> q) throws DatosInvalidosException {
        String id = q.getOrDefault("vehiculo", "CAM-D");
        return planificador.getFlota().buscar(id)
                .orElseThrow(() -> new DatosInvalidosException("Vehículo desconocido: " + id));
    }

    private static Coordenada coord(Map<String, String> q, String prefijo) throws DatosInvalidosException {
        try {
            return new Coordenada(Double.parseDouble(q.get(prefijo + "lat")), Double.parseDouble(q.get(prefijo + "lon")));
        } catch (NullPointerException | IllegalArgumentException e) {
            throw new DatosInvalidosException("Coordenada de " + (prefijo.equals("o") ? "origen" : "destino") + " inválida");
        }
    }

    /** Hora de salida pedida (8 si falta o no es un número). */
    private static int hora(Map<String, String> q) {
        try {
            return Integer.parseInt(q.getOrDefault("hora", "8"));
        } catch (NumberFormatException e) {
            return 8;
        }
    }

    /** Carga en kg pedida (2000 si falta o no es un número). */
    private static double carga(Map<String, String> q) {
        try {
            return Double.parseDouble(q.getOrDefault("carga", "2000"));
        } catch (NumberFormatException e) {
            return 2000;
        }
    }

    @FunctionalInterface
    private interface Endpoint {
        Object atender(Map<String, String> parametros) throws GreenRouteException;
    }

    /** Envuelve un endpoint: lee los parámetros, responde en JSON y convierte errores en códigos HTTP. */
    private HttpHandler api(Endpoint endpoint) {
        return ex -> {
            int codigo = 200;
            Object cuerpo;
            try {
                cuerpo = endpoint.atender(parametros(ex));
            } catch (GreenRouteException e) {
                codigo = 422;
                cuerpo = Json.obj("error", e.getCodigo(), "mensaje", e.getMessage());
            } catch (RuntimeException e) {
                codigo = 400;
                cuerpo = Json.obj("error", "SOLICITUD_INVALIDA", "mensaje", String.valueOf(e.getMessage()));
            }
            // Permite que el sitio publicado en GitHub Pages (otro dominio) consulte este API.
            ex.getResponseHeaders().set("Access-Control-Allow-Origin", "*");
            enviar(ex, codigo, "application/json; charset=utf-8", Json.escribir(cuerpo).getBytes(StandardCharsets.UTF_8));
        };
    }

    private void archivoEstatico(HttpExchange ex) throws IOException {
        String ruta = URLDecoder.decode(ex.getRequestURI().getPath(), StandardCharsets.UTF_8);
        if (ruta.endsWith("/")) ruta += "index.html";
        Path archivo = carpetaWeb.resolve(ruta.substring(1)).normalize();
        if (!archivo.startsWith(carpetaWeb) || !Files.isRegularFile(archivo)) {
            enviar(ex, 404, "text/plain; charset=utf-8", "404 — recurso no encontrado".getBytes(StandardCharsets.UTF_8));
            return;
        }
        String nombre = archivo.getFileName().toString();
        String ext = nombre.substring(nombre.lastIndexOf('.') + 1).toLowerCase();
        enviar(ex, 200, TIPOS_MIME.getOrDefault(ext, "application/octet-stream"), Files.readAllBytes(archivo));
    }

    private static Map<String, String> parametros(HttpExchange ex) {
        Map<String, String> mapa = new HashMap<>();
        String consulta = ex.getRequestURI().getRawQuery();
        if (consulta == null) return mapa;
        for (String par : consulta.split("&")) {
            int i = par.indexOf('=');
            if (i > 0) {
                mapa.put(URLDecoder.decode(par.substring(0, i), StandardCharsets.UTF_8),
                        URLDecoder.decode(par.substring(i + 1), StandardCharsets.UTF_8));
            }
        }
        return mapa;
    }

    private static void enviar(HttpExchange ex, int codigo, String tipo, byte[] datos) throws IOException {
        ex.getResponseHeaders().set("Content-Type", tipo);
        ex.getResponseHeaders().set("Cache-Control", "no-cache");
        ex.sendResponseHeaders(codigo, datos.length);
        try (OutputStream os = ex.getResponseBody()) {
            os.write(datos);
        }
    }
}

package co.edu.greenroute;

import co.edu.greenroute.analitica.PerfilHorario;
import co.edu.greenroute.api.ServidorWeb;
import co.edu.greenroute.excepciones.GreenRouteException;
import co.edu.greenroute.modelo.Coordenada;
import co.edu.greenroute.modelo.Envio;
import co.edu.greenroute.modelo.Mercancia;
import co.edu.greenroute.modelo.TipoMercancia;
import co.edu.greenroute.red.CargadorRed;
import co.edu.greenroute.red.RedTransporte;
import co.edu.greenroute.ruteo.AEstrella;
import co.edu.greenroute.ruteo.Criterio;
import co.edu.greenroute.ruteo.Ruta;
import co.edu.greenroute.servicio.PlanificadorRutas;
import co.edu.greenroute.vehiculos.Flota;
import co.edu.greenroute.vehiculos.Vehiculo;

import java.nio.file.Path;
import java.nio.file.Paths;

/** Punto de entrada: carga la red y arranca el servidor web (o, con --demo, compara la flota en consola). */
public class App {

    public static void main(String[] args) throws Exception {
        Path base = Paths.get(System.getProperty("user.dir"));
        Path datos = base.resolve("datos");
        Path web = base.resolve("..").resolve("web").normalize();
        int puerto = 8080;
        boolean demo = false;
        for (String a : args) {
            if (a.equals("--demo")) demo = true;
            else if (a.startsWith("--puerto=")) puerto = Integer.parseInt(a.substring(9));
        }

        System.out.println("==============================================================");
        System.out.println("  GREEN ROUTE · Rutas de carga de baja huella de carbono");
        System.out.println("  Barranquilla, Colombia · ODS 9 — Industria, Innovación e Infraestructura");
        System.out.println("==============================================================");
        long t0 = System.currentTimeMillis();
        RedTransporte red = CargadorRed.cargar(datos);
        PerfilHorario perfil = PerfilHorario.cargar(datos.resolve("perfil_horario.csv"));
        System.out.printf("  · Red cargada: %,d nodos, %,d tramos, %.0f km viales, %.1f km fluviales (%d ms)%n",
                red.totalNodos(), red.totalTramos(), red.getKmViales(), red.getKmFluviales(),
                System.currentTimeMillis() - t0);
        System.out.println("  · Perfil de tráfico: " + perfil.getFuente());

        PlanificadorRutas planificador = new PlanificadorRutas(red, Flota.flotaDeReferencia(), perfil, new AEstrella());

        if (demo) {
            demostracion(planificador);
            return;
        }
        new ServidorWeb(planificador, web, datos).iniciar(puerto);
        System.out.println("  · Servidor listo en  http://localhost:" + puerto);
        System.out.println("    (Ctrl + C para detener)");
    }

    private static void demostracion(PlanificadorRutas planificador) {
        Envio envio = new Envio(
                new Mercancia("Repuestos industriales", TipoMercancia.GENERAL, 900),
                new Coordenada(10.96759, -74.76222),
                new Coordenada(10.88795, -74.77950),
                7);
        System.out.println();
        System.out.println("Envío: " + envio.getMercancia() + " · Puerto → Aeropuerto · salida 7:00");
        System.out.printf("%-24s %-20s %9s %9s %11s %12s%n", "Vehículo", "Clase", "km", "min", "kg CO2e", "COP");
        System.out.println("-".repeat(90));
        for (Vehiculo v : planificador.getFlota().getVehiculos()) {
            try {
                Ruta r = planificador.planificar(envio, v, Criterio.EMISIONES);
                System.out.printf("%-24s %-20s %9.2f %9.1f %11.2f %,12.0f%n", v.getNombre(),
                        v.getClass().getSimpleName(), r.getDistanciaKm(), r.getTiempoMin(),
                        r.getEmisionKgCO2(), r.getCostoCOP());
            } catch (GreenRouteException e) {
                System.out.printf("%-24s %-20s  ✗ %s: %s%n", v.getNombre(), v.getClass().getSimpleName(),
                        e.getCodigo(), e.getMessage());
            }
        }
    }
}

package co.edu.greenroute.escritorio;

import co.edu.greenroute.analitica.PerfilHorario;
import co.edu.greenroute.excepciones.GreenRouteException;
import co.edu.greenroute.red.CargadorRed;
import co.edu.greenroute.red.RedTransporte;
import co.edu.greenroute.ruteo.AEstrella;
import co.edu.greenroute.ruteo.Criterio;
import co.edu.greenroute.servicio.PlanificadorRutas;
import co.edu.greenroute.vehiculos.Flota;

import javax.imageio.ImageIO;
import javax.swing.JComponent;
import javax.swing.JDialog;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import java.awt.Container;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;

/** Punto de entrada de la aplicación de escritorio (Swing). */
public final class AppEscritorio {

    private AppEscritorio() {
    }

    public static void main(String[] args) throws Exception {
        System.setProperty("awt.useSystemAAFontSettings", "lcd");
        System.setProperty("sun.java2d.uiScale", System.getProperty("sun.java2d.uiScale", "1"));
        Path base = Paths.get(System.getProperty("user.dir"));
        Path datos = base.resolve("datos");
        String capturas = null;
        for (String a : args) if (a.startsWith("--capturas=")) capturas = a.substring(11);

        Tema.aplicar();
        ContextoApp contexto;
        try {
            contexto = cargar(base, datos);
        } catch (GreenRouteException e) {
            JOptionPane.showMessageDialog(null, "No se pudieron cargar los datos:\n" + e.getMessage()
                    + "\n\nEjecute la aplicación desde la carpeta greenroute-java.", "Green Route", JOptionPane.ERROR_MESSAGE);
            return;
        }
        if (capturas != null) {
            ContextoApp c = contexto;
            Path destino = Paths.get(capturas);
            SwingUtilities.invokeAndWait(() -> capturar(c, destino));
            System.exit(0);
        }
        ContextoApp c = contexto;
        SwingUtilities.invokeLater(() -> menuInicial(c));
    }

    static ContextoApp cargar(Path base, Path datos) throws GreenRouteException {
        RedTransporte red = CargadorRed.cargar(datos);
        PerfilHorario perfil = PerfilHorario.cargar(datos.resolve("perfil_horario.csv"));
        PlanificadorRutas planificador = new PlanificadorRutas(red, Flota.flotaDeReferencia(), perfil, new AEstrella());
        List<PuntoLogistico> puntos = PuntoLogistico.cargar(datos.resolve("puntos.csv"));
        return new ContextoApp(planificador, puntos, base.resolve("src"));
    }

    private static void menuInicial(ContextoApp contexto) {
        String[] opciones = {"Abrir la aplicación", "Asistente paso a paso", "Salir"};
        int r = JOptionPane.showOptionDialog(null,
                String.format("<html><body style='width:330px'><h2 style='margin:0'>Green Route</h2>"
                                + "Rutas de carga de baja huella de carbono · Barranquilla<br><br>"
                                + "Red vial cargada: <b>%,d</b> intersecciones y <b>%,d</b> tramos.<br>"
                                + "¿Cómo desea empezar?</body></html>",
                        contexto.getPlanificador().getRed().totalNodos(), contexto.getPlanificador().getRed().totalTramos()),
                "Green Route", JOptionPane.DEFAULT_OPTION, JOptionPane.INFORMATION_MESSAGE, null, opciones, opciones[0]);
        switch (r) {
            case 0 -> new VentanaPrincipal(contexto).setVisible(true);
            case 1 -> {
                new AsistenteJOptionPane(contexto).iniciar(null);
                menuInicial(contexto);
            }
            default -> System.exit(0);
        }
    }

    private static void capturar(ContextoApp contexto, Path carpeta) {
        try {
            Files.createDirectories(carpeta);
            for (boolean oscuro : new boolean[]{true, false}) {
                if (Tema.esOscuro() != oscuro) {
                    Tema.alternar(new javax.swing.JWindow());
                }
                String sufijo = oscuro ? "" : "_claro";
                VentanaPrincipal v = new VentanaPrincipal(contexto);
                v.setSize(1440, 900);
                v.pack();
                v.setSize(1440, 900);
                v.validate();
                ((PantallaPlanificar) v.getPantallas().get(0)).preparar("Puerto", "Aeropuerto", 0, Criterio.EMISIONES, 600);
                guardar(v.getContentPane(), carpeta.resolve("escritorio_planificar" + sufijo + ".png"));
                v.mostrar(1);
                guardar(v.getContentPane(), carpeta.resolve("escritorio_flota" + sufijo + ".png"));
                v.mostrar(2);
                guardar(v.getContentPane(), carpeta.resolve("escritorio_herencia" + sufijo + ".png"));
                v.mostrar(3);
                ((PantallaCodigo) v.getPantallas().get(3)).abrirPorNombre("escritorio/AsistenteJOptionPane.java");
                guardar(v.getContentPane(), carpeta.resolve("escritorio_codigo" + sufijo + ".png"));
                v.dispose();
            }
            if (!Tema.esOscuro()) Tema.alternar(new javax.swing.JWindow());
            dialogo(new JOptionPane(new Object[]{"Paso 1 de 5 · ¿Desde dónde sale la carga?"}, JOptionPane.QUESTION_MESSAGE,
                    JOptionPane.OK_CANCEL_OPTION, null), contexto, true, carpeta.resolve("joption_origen.png"));
            String[] etiquetas = new String[Criterio.values().length];
            for (int i = 0; i < etiquetas.length; i++) etiquetas[i] = Criterio.values()[i].getEtiqueta();
            dialogo(new JOptionPane("Paso 5 de 5 · ¿Qué quiere optimizar?", JOptionPane.QUESTION_MESSAGE,
                    JOptionPane.DEFAULT_OPTION, null, etiquetas, etiquetas[0]), contexto, false, carpeta.resolve("joption_criterio.png"));
            var ruta = contexto.getPlanificador().planificar(contexto.punto("Puerto").getCoordenada(),
                    contexto.punto("Aeropuerto").getCoordenada(), contexto.getPlanificador().getFlota().getVehiculos().get(0),
                    Criterio.EMISIONES, 7, 600);
            dialogo(new JOptionPane(Dialogos.resumen(ruta, "Puerto de Barranquilla", "Aeropuerto Ernesto Cortissoz"),
                    JOptionPane.INFORMATION_MESSAGE), contexto, false, carpeta.resolve("joption_resultado.png"));
            try {
                contexto.getPlanificador().getFlota().getVehiculos().get(0).validarCarga(5000);
            } catch (GreenRouteException e) {
                dialogo(new JOptionPane("<html><body style='width:340px'><b>" + e.getMessage()
                        + "</b><br><br>Reduzca la carga o elija un vehículo más grande.<br><br><code>"
                        + e.getClass().getSimpleName() + " · " + e.getCodigo() + "</code></body></html>",
                        JOptionPane.WARNING_MESSAGE), contexto, false, carpeta.resolve("joption_error.png"));
            }
            System.out.println("Capturas guardadas en " + carpeta.toAbsolutePath());
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static void dialogo(JOptionPane panel, ContextoApp contexto, boolean conLista, Path archivo) throws IOException {
        if (conLista) {
            panel.setWantsInput(true);
            panel.setSelectionValues(contexto.getPuntos().toArray());
            panel.setInitialSelectionValue(contexto.punto("Puerto"));
        }
        JDialog d = panel.createDialog(null, "Green Route · Asistente");
        d.pack();
        guardar(d.getRootPane(), archivo, 2);
        d.dispose();
    }

    private static void guardar(Container c, Path archivo) throws IOException {
        guardar(c, archivo, 1);
    }

    private static void guardar(Container c, Path archivo, int escala) throws IOException {
        c.doLayout();
        c.validate();
        BufferedImage img = new BufferedImage(c.getWidth() * escala, c.getHeight() * escala, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = img.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        g.scale(escala, escala);
        if (c instanceof JComponent jc) jc.setDoubleBuffered(false);
        c.printAll(g);
        g.dispose();
        ImageIO.write(img, "png", new File(archivo.toString()));
    }
}

package co.edu.greenroute.escritorio;

import co.edu.greenroute.excepciones.GreenRouteException;
import co.edu.greenroute.ruteo.Criterio;
import co.edu.greenroute.ruteo.Ruta;
import co.edu.greenroute.servicio.OpcionTransporte;
import co.edu.greenroute.vehiculos.Vehiculo;

import javax.swing.JOptionPane;
import javax.swing.JScrollPane;
import javax.swing.JTable;
import java.awt.Component;
import java.awt.Dimension;
import java.util.List;
import java.util.Locale;

/** Asistente paso a paso con cuadros JOptionPane para planificar un envío. */
public class AsistenteJOptionPane {

    private static final String TITULO = "Green Route · Asistente";
    private final ContextoApp contexto;

    public AsistenteJOptionPane(ContextoApp contexto) {
        this.contexto = contexto;
    }

    public void iniciar(Component padre) {
        JOptionPane.showMessageDialog(padre,
                "<html><body style='width:330px'><h2 style='margin:0'>Planificador de envíos</h2><br>"
                        + "Le haré unas preguntas para calcular la ruta de <b>menor huella de carbono</b> "
                        + "entre dos puntos logísticos de Barranquilla.<br><br>"
                        + "Puede cancelar en cualquier momento.</body></html>",
                TITULO, JOptionPane.INFORMATION_MESSAGE);
        do {
            if (!planificarUnEnvio(padre)) return;
        } while (JOptionPane.showConfirmDialog(padre, "¿Desea planificar otro envío?", TITULO,
                JOptionPane.YES_NO_OPTION, JOptionPane.QUESTION_MESSAGE) == JOptionPane.YES_OPTION);
        JOptionPane.showMessageDialog(padre, "Gracias por usar Green Route. ¡Buen viaje!", TITULO,
                JOptionPane.INFORMATION_MESSAGE);
    }

    private boolean planificarUnEnvio(Component padre) {
        PuntoLogistico[] puntos = contexto.getPuntos().toArray(new PuntoLogistico[0]);

        PuntoLogistico origen = (PuntoLogistico) JOptionPane.showInputDialog(padre,
                "Paso 1 de 5 · ¿Desde dónde sale la carga?", TITULO, JOptionPane.QUESTION_MESSAGE,
                null, puntos, contexto.punto("Puerto"));
        if (origen == null) return false;
        PuntoLogistico destino;
        do {
            destino = (PuntoLogistico) JOptionPane.showInputDialog(padre,
                    "Paso 2 de 5 · ¿A dónde va?", TITULO, JOptionPane.QUESTION_MESSAGE,
                    null, puntos, contexto.punto("Aeropuerto"));
            if (destino == null) return false;
            if (destino == origen) {
                JOptionPane.showMessageDialog(padre, "El destino debe ser diferente del origen.", TITULO,
                        JOptionPane.WARNING_MESSAGE);
            }
        } while (destino == origen);

        double carga = pedirCarga(padre);
        if (carga < 0) return false;

        String[] horas = new String[24];
        for (int h = 0; h < 24; h++) horas[h] = String.format("%02d:00", h);
        String hora = (String) JOptionPane.showInputDialog(padre, "Paso 4 de 5 · Hora de salida",
                TITULO, JOptionPane.QUESTION_MESSAGE, null, horas, horas[7]);
        if (hora == null) return false;
        int h = Integer.parseInt(hora.substring(0, 2));

        Criterio[] criterios = Criterio.values();
        String[] etiquetas = new String[criterios.length];
        for (int i = 0; i < criterios.length; i++) etiquetas[i] = criterios[i].getEtiqueta();
        int elegido = JOptionPane.showOptionDialog(padre, "Paso 5 de 5 · ¿Qué quiere optimizar?", TITULO,
                JOptionPane.DEFAULT_OPTION, JOptionPane.QUESTION_MESSAGE, null, etiquetas, etiquetas[0]);
        if (elegido < 0) return false;
        Criterio criterio = criterios[elegido];

        List<Vehiculo> flota = contexto.getPlanificador().getFlota().getVehiculos();
        while (true) {
            Vehiculo vehiculo = (Vehiculo) JOptionPane.showInputDialog(padre,
                    String.format(Locale.forLanguageTag("es-CO"), "¿Con qué vehículo? (carga: %,.0f kg)", carga),
                    TITULO, JOptionPane.QUESTION_MESSAGE, null, flota.toArray(), flota.get(0));
            if (vehiculo == null) return false;
            try {
                Ruta ruta = contexto.getPlanificador().planificar(origen.getCoordenada(), destino.getCoordenada(),
                        vehiculo, criterio, h, carga);
                JOptionPane.showMessageDialog(padre, Dialogos.resumen(ruta, origen.getNombre(), destino.getNombre()),
                        "Ruta calculada", JOptionPane.INFORMATION_MESSAGE);
                break;
            } catch (GreenRouteException e) {
                Dialogos.error(padre, e);
                int otra = JOptionPane.showConfirmDialog(padre, "¿Desea intentar con otro vehículo?", TITULO,
                        JOptionPane.YES_NO_OPTION, JOptionPane.QUESTION_MESSAGE);
                if (otra != JOptionPane.YES_OPTION) return true;
            }
        }

        if (JOptionPane.showConfirmDialog(padre, "¿Quiere comparar este envío con toda la flota?", TITULO,
                JOptionPane.YES_NO_OPTION, JOptionPane.QUESTION_MESSAGE) == JOptionPane.YES_OPTION) {
            mostrarComparacion(padre, origen, destino, h, carga, criterio);
        }
        return true;
    }

    private double pedirCarga(Component padre) {
        while (true) {
            String texto = JOptionPane.showInputDialog(padre, "Paso 3 de 5 · Peso de la carga en kilogramos:", "600");
            if (texto == null) return -1;
            try {
                double kg = Double.parseDouble(texto.trim().replace(",", "."));
                if (kg <= 0) throw new NumberFormatException("debe ser positivo");
                return kg;
            } catch (NumberFormatException e) {
                JOptionPane.showMessageDialog(padre, "«" + texto + "» no es un peso válido. Escriba un número mayor que 0.",
                        "Dato inválido", JOptionPane.ERROR_MESSAGE);
            }
        }
    }

    private void mostrarComparacion(Component padre, PuntoLogistico o, PuntoLogistico d, int h, double carga,
                                    Criterio criterio) {
        List<OpcionTransporte> ops = contexto.getPlanificador()
                .compararFlota(o.getCoordenada(), d.getCoordenada(), h, carga, criterio);
        ModeloTablaFlota modelo = new ModeloTablaFlota();
        modelo.actualizar(ops);
        JTable tabla = new JTable(modelo);
        tabla.setRowHeight(30);
        tabla.getColumnModel().getColumn(5).setCellRenderer(new RenderBarra(modelo));
        JScrollPane scroll = new JScrollPane(tabla);
        scroll.setPreferredSize(new Dimension(820, 270));
        JOptionPane.showMessageDialog(padre, scroll, "Comparación de la flota · " + criterio.getEtiqueta(),
                JOptionPane.PLAIN_MESSAGE);
    }
}

package co.edu.greenroute.escritorio;

import javax.swing.JButton;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;

/** Botón Swing con el estilo visual de Green Route (dibujado a mano). */
public class BotonGR extends JButton {

    public enum Estilo { PRIMARIO, SECUNDARIO, NAVEGACION }

    private final Estilo estilo;
    private boolean activo;

    public BotonGR(String texto, Estilo estilo) {
        super(texto);
        this.estilo = estilo;
        setContentAreaFilled(false);
        setBorderPainted(false);
        setFocusPainted(false);
        setOpaque(false);
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        setFont(estilo == Estilo.NAVEGACION ? Tema.texto(14) : Tema.fuerte(14));
        setHorizontalAlignment(estilo == Estilo.NAVEGACION ? LEFT : CENTER);
    }

    public void setActivo(boolean activo) {
        this.activo = activo;
        repaint();
    }

    @Override
    public Dimension getPreferredSize() {
        FontMetrics fm = getFontMetrics(getFont());
        int ancho = fm.stringWidth(getText()) + (estilo == Estilo.NAVEGACION ? 40 : 36);
        return new Dimension(ancho, estilo == Estilo.NAVEGACION ? 40 : 42);
    }

    @Override
    protected void paintComponent(Graphics g) {
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_LCD_HRGB);
        boolean encima = getModel().isRollover();
        boolean presionado = getModel().isPressed();
        int w = getWidth(), h = getHeight(), radio = estilo == Estilo.NAVEGACION ? 12 : h;

        switch (estilo) {
            case PRIMARIO -> {
                g2.setColor(presionado ? Tema.tinta2() : Tema.tinta());
                g2.fillRoundRect(0, 0, w - 1, h - 1, radio, radio);
                g2.setColor(Tema.fondo());
            }
            case SECUNDARIO -> {
                g2.setColor(encima ? Tema.elevado() : Tema.panel());
                g2.fillRoundRect(0, 0, w - 1, h - 1, radio, radio);
                g2.setColor(encima ? Tema.tinta2() : Tema.borde());
                g2.drawRoundRect(0, 0, w - 1, h - 1, radio, radio);
                g2.setColor(Tema.tinta());
            }
            case NAVEGACION -> {
                if (activo || encima) {
                    g2.setColor(activo ? Tema.elevado() : Tema.panel());
                    g2.fillRoundRect(0, 0, w - 1, h - 1, radio, radio);
                }
                if (activo) {
                    g2.setColor(Tema.acento());
                    g2.fillRoundRect(0, 10, 4, h - 20, 4, 4);
                }
                g2.setColor(activo ? Tema.tinta() : Tema.tinta2());
            }
        }
        g2.setFont(getFont());
        FontMetrics fm = g2.getFontMetrics();
        int x = estilo == Estilo.NAVEGACION ? 18 : (w - fm.stringWidth(getText())) / 2;
        int y = (h - fm.getHeight()) / 2 + fm.getAscent();
        g2.drawString(getText(), x, y);
        g2.dispose();
    }
}

package co.edu.greenroute.escritorio;

import co.edu.greenroute.servicio.PlanificadorRutas;

import java.nio.file.Path;
import java.util.List;

/** Datos compartidos por todas las pantallas: planificador, puntos logísticos y carpeta del código. */
public final class ContextoApp {

    private final PlanificadorRutas planificador;
    private final List<PuntoLogistico> puntos;
    private final Path carpetaFuentes;

    public ContextoApp(PlanificadorRutas planificador, List<PuntoLogistico> puntos, Path carpetaFuentes) {
        this.planificador = planificador;
        this.puntos = List.copyOf(puntos);
        this.carpetaFuentes = carpetaFuentes;
    }

    public PlanificadorRutas getPlanificador() { return planificador; }
    public List<PuntoLogistico> getPuntos() { return puntos; }
    public Path getCarpetaFuentes() { return carpetaFuentes; }

    public PuntoLogistico punto(String prefijo) {
        return puntos.stream().filter(p -> p.getNombre().startsWith(prefijo)).findFirst().orElse(puntos.get(0));
    }
}

package co.edu.greenroute.escritorio;

import co.edu.greenroute.excepciones.AutonomiaInsuficienteException;
import co.edu.greenroute.excepciones.CapacidadExcedidaException;
import co.edu.greenroute.excepciones.GreenRouteException;
import co.edu.greenroute.excepciones.RutaNoEncontradaException;
import co.edu.greenroute.excepciones.VehiculoIncompatibleException;
import co.edu.greenroute.ruteo.Ruta;

import javax.swing.JOptionPane;
import java.awt.Component;
import java.util.Locale;

/** Mensajes JOptionPane reutilizables (errores y resumen de una ruta). */
public final class Dialogos {

    private Dialogos() {
    }

    public static void error(Component padre, GreenRouteException e) {
        String titulo;
        int tipo;
        String consejo;
        switch (e) {
            case CapacidadExcedidaException c -> {
                titulo = "Carga excedida";
                tipo = JOptionPane.WARNING_MESSAGE;
                consejo = String.format(Locale.ROOT, "Reduzca la carga a %.0f kg o elija un vehículo más grande.", c.getCapacidadKg());
            }
            case AutonomiaInsuficienteException a -> {
                titulo = "Autonomía insuficiente";
                tipo = JOptionPane.WARNING_MESSAGE;
                consejo = "La batería no alcanza: use un vehículo con más autonomía o una parada de recarga.";
            }
            case VehiculoIncompatibleException v -> {
                titulo = "Vehículo incompatible";
                tipo = JOptionPane.ERROR_MESSAGE;
                consejo = "La barcaza solo navega el río Magdalena; los camiones no pueden usar el río.";
            }
            case RutaNoEncontradaException r -> {
                titulo = "Sin ruta";
                tipo = JOptionPane.ERROR_MESSAGE;
                consejo = "Elija un origen y un destino diferentes.";
            }
            default -> {
                titulo = "Green Route";
                tipo = JOptionPane.ERROR_MESSAGE;
                consejo = "";
            }
        }
        JOptionPane.showMessageDialog(padre,
                "<html><body style='width:340px'><b>" + e.getMessage() + "</b><br><br>"
                        + "<span style='color:" + Tema.hex(Tema.tinta2()) + "'>" + consejo + "</span><br><br>"
                        + "<code>" + e.getClass().getSimpleName() + " · " + e.getCodigo() + "</code></body></html>",
                titulo, tipo);
    }

    public static String resumen(Ruta r, String origen, String destino) {
        String gris = Tema.hex(Tema.tinta2());
        String verde = Tema.hex(Tema.acento());
        return String.format(Locale.forLanguageTag("es-CO"), """
                <html><body style='width:360px'>
                <div style='font-size:15pt'><b>%s</b></div>
                <div style='color:%s'>%s → %s</div><br>
                <table cellpadding='3'>
                  <tr><td style='color:%s'>Distancia</td><td><b>%.2f km</b></td></tr>
                  <tr><td style='color:%s'>Tiempo</td><td><b>%.0f min</b></td></tr>
                  <tr><td style='color:%s'>Emisiones</td><td><b style='color:%s'>%.2f kg CO₂e</b></td></tr>
                  <tr><td style='color:%s'>Costo de energía</td><td><b>$ %,.0f COP</b></td></tr>
                  <tr><td style='color:%s'>Criterio</td><td>%s</td></tr>
                  <tr><td style='color:%s'>Algoritmo</td><td>%s · %,d nodos explorados</td></tr>
                </table></body></html>""",
                r.getVehiculo().getNombre(), gris, origen, destino,
                gris, r.getDistanciaKm(), gris, r.getTiempoMin(), gris, verde, r.getEmisionKgCO2(),
                gris, r.getCostoCOP(), gris, r.getCriterio().getEtiqueta(), gris, r.getAlgoritmo(),
                r.getNodosExplorados())
                .replace("\n", "");
    }
}

package co.edu.greenroute.escritorio;

import javax.swing.Icon;
import java.awt.Color;
