        };
        codigo.add(titulo, BorderLayout.NORTH);
        codigo.add(fragmento, BorderLayout.CENTER);
        return armar(scroll, codigo, pie);
    }

    private static String htmlFragmento() {
        String v = Tema.hex(Tema.acento()), c = Tema.hex(Tema.tenue()), t = Tema.hex(Tema.tinta());
        return "<html><pre style='font-family:Consolas;font-size:11pt;color:" + t + "'>"
                        + "<b style='color:" + v + "'>for</b> (Vehiculo v : flota.getVehiculos()) {   <span style='color:" + c + "'>// List&lt;Vehiculo&gt;: tipo abstracto</span>\n"
                        + "    <b style='color:" + v + "'>try</b> {\n"
                        + "        Ruta r = planificar(o, d, v, criterio, hora, carga);  <span style='color:" + c + "'>// polimorfismo: cada clase calcula su consumo</span>\n"
                        + "        opciones.add(OpcionTransporte.factible(v, r));\n"
                        + "    } <b style='color:" + v + "'>catch</b> (GreenRouteException e) {               <span style='color:" + c + "'>// excepción propia: barcaza fuera del río</span>\n"
                        + "        opciones.add(OpcionTransporte.noFactible(v, e));\n"
                        + "    }\n}</pre></html>";
    }

    private static JComponent armar(JScrollPane scroll, Tarjeta codigo, JPanel pie) {
        JPanel arriba = new JPanel(new BorderLayout(0, 18));
        arriba.setOpaque(false);
        arriba.add(scroll, BorderLayout.NORTH);
        arriba.add(codigo, BorderLayout.CENTER);
        JPanel cuerpo = new JPanel(new BorderLayout(0, 18));
        cuerpo.setOpaque(false);
        cuerpo.add(arriba, BorderLayout.NORTH);
        cuerpo.add(pie, BorderLayout.SOUTH);
        return cuerpo;
    }

    @Override
    public void alMostrar() {
        if (modelo.getRowCount() == 0) comparar();
    }

    public void comparar() {
        PuntoLogistico o = contexto.punto("Puerto"), d = contexto.punto("Aeropuerto");
        List<OpcionTransporte> ops = contexto.getPlanificador()
                .compararFlota(o.getCoordenada(), d.getCoordenada(), 7, 600, Criterio.EMISIONES);
        modelo.actualizar(ops);
        Optional<OpcionTransporte> mejor = contexto.getPlanificador().recomendar(ops);
        double peor = modelo.getMaximaEmision();
        mejor.ifPresent(m -> lblConclusion.setText(String.format(Locale.forLanguageTag("es-CO"),
                "<html>Recomendado: <b>%s</b> · %.2f kg CO₂e, <b>%.0f %% menos</b> que la peor opción. "
                        + "<span style='color:%s'>(doble clic en una fila para ver el detalle)</span></html>",
                m.getVehiculo().getNombre(), m.getRuta().getEmisionKgCO2(),
                (1 - m.getRuta().getEmisionKgCO2() / peor) * 100, Tema.hex(Tema.tenue()))));
    }

    private void detalle(OpcionTransporte op) {
        if (op.esFactible()) {
            JOptionPane.showMessageDialog(this, Dialogos.resumen(op.getRuta(), "Puerto", "Aeropuerto"),
                    op.getVehiculo().getClass().getSimpleName(), JOptionPane.INFORMATION_MESSAGE);
        } else {
            JOptionPane.showMessageDialog(this, "<html><body style='width:320px'>" + op.aMapa().get("motivo") + "</body></html>",
                    op.getVehiculo().getNombre() + " · no factible", JOptionPane.WARNING_MESSAGE);
        }
    }
}

package co.edu.greenroute.escritorio;

import co.edu.greenroute.vehiculos.Vehiculo;

import javax.swing.JComponent;
import javax.swing.JOptionPane;
import java.awt.BasicStroke;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.stream.Collectors;

/** Pantalla que dibuja el árbol de herencia de los vehículos. */
public class PantallaJerarquia extends Pantalla {

    public PantallaJerarquia(ContextoApp contexto) {
        super(contexto);
    }

    @Override public String getTitulo() { return "Herencia y polimorfismo"; }
    @Override public String getSubtitulo() { return "Árbol real de clases obtenido por reflexión. Haga clic en una clase para ver qué métodos redefine."; }

    @Override
    protected JComponent construirContenido() {
        return new Arbol(contexto.getPlanificador().getFlota().getVehiculos());
    }

    private static final class Arbol extends JComponent {

        private final Map<Class<?>, List<Class<?>>> hijos = new LinkedHashMap<>();
        private final Map<Class<?>, Vehiculo> instancia = new LinkedHashMap<>();
        private final Map<Class<?>, Rectangle> cajas = new LinkedHashMap<>();
        private final Map<Class<?>, Double> columna = new LinkedHashMap<>();
        private int hojas;

        Arbol(List<Vehiculo> flota) {
            for (Vehiculo v : flota) {
                instancia.put(v.getClass(), v);
                Class<?> c = v.getClass();
                while (c != Vehiculo.class) {
                    Class<?> padre = c.getSuperclass();
                    List<Class<?>> lista = hijos.computeIfAbsent(padre, k -> new ArrayList<>());
                    if (!lista.contains(c)) lista.add(c);
                    c = padre;
                }
            }
            ubicar(Vehiculo.class);
            addMouseListener(new MouseAdapter() {
                @Override
                public void mouseClicked(MouseEvent e) {
                    cajas.forEach((clase, r) -> { if (r.contains(e.getPoint())) explicar(clase); });
                }
            });
        }

        private double ubicar(Class<?> c) {
            List<Class<?>> h = hijos.getOrDefault(c, List.of());
            double x;
            if (h.isEmpty()) {
                x = hojas++;
            } else {
                x = h.stream().mapToDouble(this::ubicar).average().orElse(0);
            }
            columna.put(c, x);
            return x;
        }

        private int nivel(Class<?> c) {
            int n = 0;
            while (c != Vehiculo.class) { c = c.getSuperclass(); n++; }
            return n;
        }

        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_LCD_HRGB);
            int anchoCaja = 178, altoCaja = 64, sepY = 120;
            double paso = (getWidth() - anchoCaja - 20) / Math.max(1.0, hojas - 1);
            cajas.clear();
            columna.forEach((c, col) -> cajas.put(c, new Rectangle((int) (10 + col * paso), 46 + nivel(c) * sepY, anchoCaja, altoCaja)));

            Rectangle raiz = cajas.get(Vehiculo.class);
            Rectangle emisor = new Rectangle(raiz.x, 0, anchoCaja, 30);
            g2.setColor(Tema.tenue());
            g2.setStroke(new BasicStroke(1.4f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 10, new float[]{5, 4}, 0));
            g2.drawLine(raiz.x + anchoCaja / 2, raiz.y, raiz.x + anchoCaja / 2, emisor.y + emisor.height);
            g2.setStroke(new BasicStroke(1.4f));
            g2.drawRoundRect(emisor.x, emisor.y, emisor.width, emisor.height, 10, 10);
            g2.setFont(Tema.mono(12));
            centrado(g2, "«interface» Emisor", emisor, emisor.y + 20);

            g2.setStroke(new BasicStroke(1.6f));
            for (Map.Entry<Class<?>, List<Class<?>>> e : hijos.entrySet()) {
                Rectangle p = cajas.get(e.getKey());
                int ty = p.y + p.height + 12, px = p.x + p.width / 2;
                int medio = ty + 22;
                g2.setColor(Tema.tenue());
                for (Class<?> h : e.getValue()) {
                    Rectangle r = cajas.get(h);
                    int hx = r.x + r.width / 2;
                    g2.drawLine(hx, r.y, hx, medio);
                    g2.drawLine(hx, medio, px, medio);
                }
                g2.drawLine(px, medio, px, ty);
                Polygon tri = new Polygon(new int[]{px - 8, px + 8, px}, new int[]{ty, ty, ty - 12}, 3);
                g2.setColor(Tema.fondo());
                g2.fill(tri);
                g2.setColor(Tema.tinta2());
                g2.draw(tri);
            }

            for (Map.Entry<Class<?>, Rectangle> e : cajas.entrySet()) caja(g2, e.getKey(), e.getValue());

            int y0 = 46 + 3 * sepY + altoCaja + 50;
            g2.setColor(Tema.panel());
            g2.fillRoundRect(10, y0, getWidth() - 20, 112, 16, 16);
            g2.setColor(Tema.borde());
            g2.drawRoundRect(10, y0, getWidth() - 20, 112, 16, 16);
            g2.setFont(Tema.mono(14));
            String[] codigo = {
                    "for (Vehiculo v : flota.getVehiculos()) {          // el tipo declarado es la clase abstracta",
                    "    double g = v.emisionMinimaPorMetro(600) * 1e6;  // enlace dinámico: cada subclase usa su consumoPorKm()",
                    "}"};
            for (int i = 0; i < codigo.length; i++) {
                int cx = 30, cy = y0 + 34 + i * 26;
                String linea = codigo[i];
                int corte = linea.indexOf("//");
                String sentencia = corte >= 0 ? linea.substring(0, corte) : linea;
                g2.setColor(Tema.tinta());
                g2.drawString(sentencia, cx, cy);
                if (corte >= 0) {
                    g2.setColor(Tema.acento());
                    g2.drawString(linea.substring(corte), cx + g2.getFontMetrics().stringWidth(sentencia), cy);
                }
            }
            g2.dispose();
        }

        private void caja(Graphics2D g2, Class<?> c, Rectangle r) {
            boolean abstracta = Modifier.isAbstract(c.getModifiers());
            Vehiculo v = instancia.get(c);
            g2.setColor(abstracta ? Tema.panel() : Tema.elevado());
            g2.fillRoundRect(r.x, r.y, r.width, r.height, 14, 14);
            g2.setColor(v != null ? Tema.acento() : Tema.borde());
            g2.setStroke(new BasicStroke(v != null ? 1.8f : 1.2f));
            g2.drawRoundRect(r.x, r.y, r.width, r.height, 14, 14);
            g2.setFont(Tema.mono(11));
            g2.setColor(Tema.tenue());
            String estereotipo = abstracta ? "«abstract»" : Arrays.stream(c.getInterfaces())
                    .map(i -> "implements " + i.getSimpleName()).collect(Collectors.joining(", "));
            centrado(g2, estereotipo, r, r.y + 18);
            g2.setFont(Tema.fuerte(14));
            g2.setColor(Tema.tinta());
            centrado(g2, c.getSimpleName(), r, r.y + 38);
            if (v != null) {
                g2.setFont(Tema.mono(12));
                g2.setColor(Tema.acento());
                double g = v.emisionMinimaPorMetro(600) * 1_000_000;
                centrado(g2, String.format(Locale.forLanguageTag("es-CO"), "mín. %,.0f g CO₂/km", g), r, r.y + 56);
            }
        }

        private static void centrado(Graphics2D g2, String s, Rectangle r, int y) {
            int w = g2.getFontMetrics().stringWidth(s);
            g2.drawString(s, r.x + (r.width - w) / 2, y);
        }

        private void explicar(Class<?> c) {
            String metodos = Arrays.stream(c.getDeclaredMethods())
                    .filter(m -> !m.isSynthetic() && !Modifier.isPrivate(m.getModifiers()))
                    .map(Method::getName).distinct().sorted()
                    .map(n -> "<li><code>" + n + "()</code></li>").collect(Collectors.joining());
            String padre = c.getSuperclass().getSimpleName();
            String interfaces = Arrays.stream(c.getInterfaces()).map(Class::getSimpleName).collect(Collectors.joining(", "));
            JOptionPane.showMessageDialog(this, "<html><body style='width:330px'>"
                    + "<code>public " + (Modifier.isAbstract(c.getModifiers()) ? "abstract " : "") + "class "
                    + c.getSimpleName() + " extends " + padre + (interfaces.isEmpty() ? "" : " implements " + interfaces)
                    + "</code><br><br><b>Métodos que declara o redefine:</b><ul>" + metodos + "</ul></body></html>",
                    c.getSimpleName(), JOptionPane.INFORMATION_MESSAGE);
        }
    }
}

package co.edu.greenroute.escritorio;

import co.edu.greenroute.excepciones.GreenRouteException;
import co.edu.greenroute.ruteo.Criterio;
import co.edu.greenroute.ruteo.Ruta;
import co.edu.greenroute.vehiculos.Vehiculo;

import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSlider;
import javax.swing.JSpinner;
import javax.swing.SpinnerNumberModel;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.Locale;

/** Pantalla principal: elegir origen, destino, vehículo y criterio, y ver la ruta. */
public class PantallaPlanificar extends Pantalla {

    private JComboBox<PuntoLogistico> cbOrigen;
    private JComboBox<PuntoLogistico> cbDestino;
    private JComboBox<Vehiculo> cbVehiculo;
    private JComboBox<Criterio> cbCriterio;
    private JSpinner spCarga;
    private JSlider slHora;
    private JLabel lblHora;
    private JLabel lblResultado;
    private PanelMapa mapa;

    public PantallaPlanificar(ContextoApp contexto) {
        super(contexto);
    }

    @Override public String getTitulo() { return "Planificar ruta"; }
    @Override public String getSubtitulo() { return "Elija origen, destino, vehículo y criterio: el motor A* calcula la ruta sobre la malla vial real."; }

    @Override
    protected JComponent construirContenido() {
        cbOrigen = new JComboBox<>(contexto.getPuntos().toArray(new PuntoLogistico[0]));
        cbDestino = new JComboBox<>(contexto.getPuntos().toArray(new PuntoLogistico[0]));
        cbOrigen.setSelectedItem(contexto.punto("Puerto"));
        cbDestino.setSelectedItem(contexto.punto("Aeropuerto"));
        cbVehiculo = new JComboBox<>(contexto.getPlanificador().getFlota().getVehiculos().toArray(new Vehiculo[0]));
        cbVehiculo.setRenderer((lista, v, i, sel, foco) -> new JLabel(v == null ? "" : v.getNombre()) {{
            setOpaque(true);
            setBorder(BorderFactory.createEmptyBorder(4, 8, 4, 8));
            setBackground(sel ? Tema.borde() : Tema.elevado());
            setForeground(Tema.tinta());
        }});
        cbCriterio = new JComboBox<>(Criterio.values());
        cbCriterio.setRenderer((lista, c, i, sel, foco) -> new JLabel(c == null ? "" : c.getEtiqueta()) {{
            setOpaque(true);
            setBorder(BorderFactory.createEmptyBorder(4, 8, 4, 8));
            setBackground(sel ? Tema.borde() : Tema.elevado());
            setForeground(Tema.tinta());
        }});
        spCarga = new JSpinner(new SpinnerNumberModel(600, 50, 40_000, 50));
        slHora = new JSlider(0, 23, 7);
        lblHora = new JLabel();
        slHora.addChangeListener(e -> lblHora.setText(String.format("Salida: %02d:00", slHora.getValue())));
        lblHora.setText("Salida: 07:00");

        BotonGR calcular = new BotonGR("Calcular ruta", BotonGR.Estilo.PRIMARIO);
        BotonGR asistente = new BotonGR("Asistente paso a paso", BotonGR.Estilo.SECUNDARIO);
        calcular.addActionListener(e -> calcular());
        asistente.addActionListener(e -> new AsistenteJOptionPane(contexto).iniciar(this));

        Tarjeta formulario = new Tarjeta(null);
        formulario.setLayout(new BoxLayout(formulario, BoxLayout.Y_AXIS));
        campo(formulario, "Origen", cbOrigen);
        campo(formulario, "Destino", cbDestino);
        campo(formulario, "Vehículo", cbVehiculo);
        campo(formulario, "Criterio de optimización", cbCriterio);
        campo(formulario, "Carga (kg)", spCarga);
        campo(formulario, "Hora de salida", slHora);
        formulario.add(lblHora);
        formulario.add(Box.createVerticalStrut(16));
        JPanel botones = new JPanel(new GridLayout(1, 2, 10, 0));
        botones.setOpaque(false);
        botones.setAlignmentX(Component.LEFT_ALIGNMENT);
        botones.add(calcular);
        botones.add(asistente);
        botones.setMaximumSize(new Dimension(Integer.MAX_VALUE, 44));
        formulario.add(botones);
        formulario.add(Box.createVerticalStrut(18));
        lblResultado = new JLabel("<html>Presione <b>Calcular ruta</b>.</html>");
        lblResultado.setAlignmentX(Component.LEFT_ALIGNMENT);
        lblResultado.setVerticalAlignment(JLabel.TOP);
        formulario.add(lblResultado);
        formulario.setPreferredSize(new Dimension(430, 600));

        mapa = new PanelMapa(contexto.getPlanificador().getRed());
        JPanel cuerpo = new JPanel(new BorderLayout(20, 0));
        cuerpo.setOpaque(false);
        cuerpo.add(formulario, BorderLayout.WEST);
        cuerpo.add(mapa, BorderLayout.CENTER);
        return cuerpo;
    }

    private static void campo(JPanel destino, String rotulo, JComponent control) {
        JLabel r = rotulo(rotulo);
        r.setAlignmentX(Component.LEFT_ALIGNMENT);
        r.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
        control.setAlignmentX(Component.LEFT_ALIGNMENT);
        control.setMaximumSize(new Dimension(Integer.MAX_VALUE, 34));
        destino.add(r);
        destino.add(control);
        destino.add(Box.createVerticalStrut(12));
    }

    public void calcular() {
        PuntoLogistico o = (PuntoLogistico) cbOrigen.getSelectedItem();
        PuntoLogistico d = (PuntoLogistico) cbDestino.getSelectedItem();
        Vehiculo v = (Vehiculo) cbVehiculo.getSelectedItem();
        Criterio c = (Criterio) cbCriterio.getSelectedItem();
        double carga = ((Number) spCarga.getValue()).doubleValue();
        try {
            Ruta r = contexto.getPlanificador().planificar(o.getCoordenada(), d.getCoordenada(), v, c,
                    slHora.getValue(), carga);
            mapa.mostrar(r, o.getCoordenada(), d.getCoordenada());
            lblResultado.setText(Dialogos.resumen(r, o.getNombre(), d.getNombre()));
        } catch (GreenRouteException ex) {
            mapa.mostrar(null, o.getCoordenada(), d.getCoordenada());
            lblResultado.setText(String.format(Locale.ROOT, "<html><b>Sin ruta:</b> %s</html>", ex.getMessage()));
            Dialogos.error(this, ex);
        }
    }

    void preparar(String origen, String destino, int indiceVehiculo, Criterio criterio, double carga) {
        cbOrigen.setSelectedItem(contexto.punto(origen));
        cbDestino.setSelectedItem(contexto.punto(destino));
        cbVehiculo.setSelectedIndex(indiceVehiculo);
        cbCriterio.setSelectedItem(criterio);
        spCarga.setValue((int) carga);
        calcular();
    }
}

package co.edu.greenroute.escritorio;

import co.edu.greenroute.excepciones.DatosInvalidosException;
import co.edu.greenroute.modelo.Coordenada;
import co.edu.greenroute.util.LectorCSV;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

/** Lugar con nombre (puerto, aeropuerto, ...) leído de puntos.csv. */
public final class PuntoLogistico {

    private final String nombre;
    private final String categoria;
    private final Coordenada coordenada;

    public PuntoLogistico(String nombre, String categoria, Coordenada coordenada) {
        this.nombre = nombre;
        this.categoria = categoria;
        this.coordenada = coordenada;
    }

    public static List<PuntoLogistico> cargar(Path archivo) throws DatosInvalidosException {
        List<PuntoLogistico> puntos = new ArrayList<>();
        LectorCSV.leer(archivo, fila -> puntos.add(new PuntoLogistico(
                fila.get("nombre"), fila.get("categoria"),
                new Coordenada(Double.parseDouble(fila.get("lat")), Double.parseDouble(fila.get("lon"))))));
        return puntos;
    }

    public String getNombre() { return nombre; }
    public String getCategoria() { return categoria; }
    public Coordenada getCoordenada() { return coordenada; }

    @Override
    public String toString() {
        return nombre + "  ·  " + categoria;
    }
}

package co.edu.greenroute.escritorio;

import javax.swing.JTable;
import javax.swing.table.DefaultTableCellRenderer;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.util.Locale;

/** Dibuja una barra proporcional dentro de una celda de la tabla. */
public class RenderBarra extends DefaultTableCellRenderer {

    private final ModeloTablaFlota modelo;
    private double fraccion;
    private boolean minima;

    public RenderBarra(ModeloTablaFlota modelo) {
        this.modelo = modelo;
        setHorizontalAlignment(LEFT);
    }

    @Override
    public Component getTableCellRendererComponent(JTable tabla, Object valor, boolean sel, boolean foco,
                                                   int fila, int col) {
        super.getTableCellRendererComponent(tabla, "", sel, false, fila, col);
        if (valor instanceof Double kg) {
            fraccion = kg / modelo.getMaximaEmision();
            minima = fila == indiceMinimo();
            setText(String.format(Locale.forLanguageTag("es-CO"), "   %.2f", kg));
        } else {
            fraccion = 0;
            minima = false;
            setText("   —");
        }
        setForeground(Tema.tinta());
        setBackground(sel ? Tema.borde() : Tema.elevado());
        return this;
    }

    private int indiceMinimo() {
        int mejor = -1;
        double min = Double.MAX_VALUE;
        for (int i = 0; i < modelo.getRowCount(); i++) {
            Object v = modelo.getValueAt(i, 5);
            if (v instanceof Double d && d < min) { min = d; mejor = i; }
        }
        return mejor;
    }

    @Override
    protected void paintComponent(Graphics g) {
        g.setColor(getBackground());
        g.fillRect(0, 0, getWidth(), getHeight());
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        int ancho = (int) Math.round((getWidth() - 80) * fraccion);
        g2.setColor(minima ? Tema.acento() : Tema.tenue());
        g2.fillRoundRect(64, getHeight() / 2 - 5, Math.max(ancho, fraccion > 0 ? 3 : 0), 10, 4, 4);
        g2.dispose();
        setOpaque(false);
        super.paintComponent(g);
        setOpaque(true);
    }
}

